import {createClient} from 'npm:@supabase/supabase-js@2.112.4';

const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const SUPABASE_URL=Deno.env.get('SUPABASE_URL')!;
const db=createClient(SUPABASE_URL,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
const PROVIDER='immowelt';
const START='https://signin.immowelt.de/?target=portal&path=%2F';
const UA='Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 Chrome/131.0 Mobile Safari/537.36';
const enc=new TextEncoder(),dec=new TextDecoder();

type CookieRec={name:string,value:string,domain:string,path:string,expires:number,httpOnly:boolean,secure:boolean,sameSite?:string,hostOnly:boolean};
type Jar=Map<string,CookieRec>;

const clean=(v:any,max=500)=>String(v??'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
const b64=(bytes:Uint8Array)=>{let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s)};
const unb64=(value:string)=>Uint8Array.from(atob(value),c=>c.charCodeAt(0));
const b64url=(bytes:Uint8Array)=>b64(bytes).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const unb64url=(value:string)=>unb64(value.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(value.length/4)*4,'='));

async function secret(name:string){const{data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)throw Error('configuration_unavailable');return String(data)}
async function keyMaterial(){const raw=unb64(await secret('application_credential_key_v1'));if(raw.length!==32)throw Error('credential_key_invalid');return crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function sealMfa(value:any){const key=await keyMaterial(),iv=crypto.getRandomValues(new Uint8Array(12)),plain=enc.encode(JSON.stringify(value)),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:enc.encode('immowelt:mfa:v1')},key,plain));return b64url(iv)+'.'+b64url(cipher)}
async function openMfa(value:string){const parts=String(value||'').split('.');if(parts.length!==2)throw Error('mfa_expired');try{const key=await keyMaterial(),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64url(parts[0]),additionalData:enc.encode('immowelt:mfa:v1')},key,unb64url(parts[1])),data=JSON.parse(dec.decode(plain));if(!data?.exp||Date.now()>Number(data.exp))throw Error('mfa_expired');return data}catch(e:any){if(e?.message==='mfa_expired')throw e;throw Error('mfa_expired')}}
function uuid(v:any){const s=String(v||'');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s))throw Error('invalid_user');return s}
function email(v:any){const s=clean(v,320).toLowerCase();return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)?s:null}
async function eligible(userId:string){const{data,error}=await db.rpc('application_user_eligible',{p_user:userId});if(error||data!==true)throw Error('premium_required')}
async function flowByState(state:any,userId?:string){const s=String(state||'');if(!/^[A-Za-z0-9_-]{20,100}$/.test(s))throw Error('invalid_state');let q=db.from('platform_auth_flows').select('*').eq('provider',PROVIDER).eq('state',s).is('consumed_at',null).gt('expires_at',new Date().toISOString());if(userId)q=q.eq('user_id',userId);const{data,error}=await q.maybeSingle();if(error||!data)throw Error('auth_flow_expired');await eligible(String(data.user_id));return data}

function decodeHtml(v:string){return String(v||'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>')}
function attr(tag:string,name:string){const re=new RegExp('\\b'+name+'\\s*=\\s*["\\\']([^"\\\']*)["\\\']','i'),m=tag.match(re);return m?decodeHtml(m[1]):null}
function defaultPath(path:string){if(!path||path[0]!=='/'||path==='/')return'/';const i=path.lastIndexOf('/');return i<=0?'/':path.slice(0,i+1)}
function cookieKey(c:CookieRec){return c.domain+'|'+c.path+'|'+c.name}
function setCookies(headers:Headers,urlValue:string,jar:Jar){const url=new URL(urlValue),lines:string[]=(headers as any).getSetCookie?.()||[];if(!lines.length&&headers.get('set-cookie'))lines.push(String(headers.get('set-cookie')));for(const line of lines){const parts=String(line||'').split(';').map(x=>x.trim()).filter(Boolean),first=parts.shift()||'',eq=first.indexOf('=');if(eq<=0)continue;const name=first.slice(0,eq).trim(),value=first.slice(eq+1),rec:CookieRec={name,value,domain:url.hostname.toLowerCase(),path:defaultPath(url.pathname),expires:-1,httpOnly:false,secure:false,hostOnly:true};let maxAge:null|number=null;for(const p of parts){const j=p.indexOf('='),k=(j<0?p:p.slice(0,j)).trim().toLowerCase(),v=j<0?'':p.slice(j+1).trim();if(k==='domain'&&v){rec.domain=v.replace(/^\./,'').toLowerCase();rec.hostOnly=false}else if(k==='path'&&v)rec.path=v;else if(k==='max-age')maxAge=Number(v);else if(k==='expires'){const ms=Date.parse(v);if(Number.isFinite(ms))rec.expires=Math.floor(ms/1000)}else if(k==='httponly')rec.httpOnly=true;else if(k==='secure')rec.secure=true;else if(k==='samesite'&&v)rec.sameSite=v[0].toUpperCase()+v.slice(1).toLowerCase()}if(maxAge!==null&&Number.isFinite(maxAge))rec.expires=maxAge<=0?0:Math.floor(Date.now()/1000+maxAge);const key=cookieKey(rec);if(rec.expires===0||value==='')jar.delete(key);else jar.set(key,rec)}}
function cookieMatch(c:CookieRec,url:URL){const host=url.hostname.toLowerCase(),domain=c.domain.toLowerCase(),domainOk=c.hostOnly?host===domain:(host===domain||host.endsWith('.'+domain));if(!domainOk)return false;if(c.secure&&url.protocol!=='https:')return false;if(c.expires>0&&c.expires<=Date.now()/1000)return false;return url.pathname.startsWith(c.path||'/')}
function cookieHeader(jar:Jar,urlValue:string){const url=new URL(urlValue);return[...jar.values()].filter(c=>cookieMatch(c,url)).map(c=>c.name+'='+c.value).join('; ')}
function sessionCookies(jar:Jar){return[...jar.values()].filter(c=>(c.domain==='immowelt.de'||c.domain.endsWith('.immowelt.de')||c.domain==='signin.immowelt.de')&&(c.expires<0||c.expires>Date.now()/1000)).map(c=>({name:c.name,value:c.value,domain:c.hostOnly?c.domain:'.'+c.domain,path:c.path||'/',expires:c.expires,httpOnly:c.httpOnly,secure:c.secure,sameSite:c.sameSite}))}
async function request(url:string,init:RequestInit,jar:Jar){const headers=new Headers(init.headers||{}),cookie=cookieHeader(jar,url);if(cookie)headers.set('cookie',cookie);headers.set('user-agent',UA);headers.set('accept-language','de-DE,de;q=0.9,en;q=0.8');let r:Response;try{r=await fetch(url,{...init,headers,redirect:'manual',signal:AbortSignal.timeout(25000)})}catch{throw Error('temporary_network_error')}setCookies(r.headers,url,jar);return r}

function primaryForm(html:string){const form=html.match(/<form[^>]*data-form-primary=["']true["'][^>]*>[\s\S]*?<\/form>/i)?.[0]||html.match(/<form[^>]*>[\s\S]*?<\/form>/i)?.[0];if(!form)return null;const open=form.match(/^<form[^>]*>/i)?.[0]||'',action=attr(open,'action');return{html:form,action}}
function formInputs(form:string){const out:Record<string,string>={};for(const m of form.matchAll(/<input[^>]*>/gi)){const tag=m[0],name=attr(tag,'name');if(!name)continue;out[name]=attr(tag,'value')||''}return out}
function hasCredentialForm(html:string){const f=primaryForm(html)?.html||'';return /name=["']username["']/i.test(f)&&/name=["']password["']/i.test(f)}
function codeField(html:string){const f=primaryForm(html)?.html||'';for(const m of f.matchAll(/<input[^>]*>/gi)){const tag=m[0],name=attr(tag,'name')||'',type=(attr(tag,'type')||'text').toLowerCase();if(type==='hidden'||name==='username'||name==='password'||name==='state')continue;if(/code|otp|passcode|token|mfa/i.test(name)||/one-time-code/i.test(tag))return name}return null}
function challengeType(html:string){const text=clean(html.replace(/<[^>]+>/g,' '),10000).toLowerCase();if(/authenticator|totp/.test(text))return'token:software:totp';if(/sms|mobilfunk|telefonnummer/.test(text))return'sms';if(/e-?mail|email/.test(text))return'email';return'code'}
function factorLabel(type:string){return type==='email'?'Code per E-Mail':type==='sms'?'Code per SMS':type==='token:software:totp'?'Authenticator-App':'Bestätigungscode'}
function isHumanCheck(html:string){const text=clean(html.replace(/<[^>]+>/g,' '),10000).toLowerCase();return/captcha|verify you are human|ich bin kein roboter|sicherheitsüberprüfung/.test(text)}
function isDeviceConfirmation(html:string){const text=clean(html.replace(/<[^>]+>/g,' '),10000).toLowerCase();return/(bestätige|confirm|verify).{0,80}(e-?mail|gerät|device)|(e-?mail|gerät|device).{0,80}(bestätige|confirm|verify)/.test(text)&&!codeField(html)}
async function mfaResult(flow:any,emailValue:string,url:string,html:string,jar:Jar){const field=codeField(html);if(!field){if(isDeviceConfirmation(html))throw Error('device_confirmation_required');throw Error('provider_interactive_challenge')}const form=primaryForm(html);if(!form)throw Error('provider_contract_unverified');const hidden=formInputs(form.html),type=challengeType(html),ticket=await sealMfa({v:1,exp:Date.now()+10*60*1000,flowState:String(flow.state),userId:String(flow.user_id),email:emailValue,url,hidden,codeField:field,type,cookies:[...jar.values()]});return{status:'mfa_required',authenticated:false,mfaRequired:true,codeDispatched:true,mfaTicket:ticket,factors:[{id:'immowelt_code',type,label:factorLabel(type)}]}}
function success(flow:any,emailValue:string,jar:Jar){const cookies=sessionCookies(jar);if(!cookies.length)throw Error('provider_completion_failed');return{status:'connected',authenticated:true,accountHint:emailValue,passwordStored:false,session:{cookies,userAgent:UA}}}

async function settle(flow:any,emailValue:string,startUrl:string,response:Response,jar:Jar,afterCredential:boolean){let url=startUrl,r=response;for(let i=0;i<12;i++){if(r.status>=300&&r.status<400){const location=r.headers.get('location');if(!location)throw Error('provider_contract_unverified');url=new URL(location,url).href;r=await request(url,{method:'GET',headers:{accept:'text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8'}},jar);continue}const html=await r.text().catch(()=>''),host=new URL(url).hostname.toLowerCase();if(host==='signin.immowelt.de'){if(isHumanCheck(html))throw Error('human_verification_required');if(codeField(html)||isDeviceConfirmation(html))return mfaResult(flow,emailValue,url,html,jar);if(hasCredentialForm(html)){if(afterCredential)throw Error('login_failed');throw Error('provider_contract_unverified')}throw Error('provider_interactive_challenge')}if(host==='immowelt.de'||host.endsWith('.immowelt.de'))return success(flow,emailValue,jar);throw Error('provider_contract_unverified')}throw Error('provider_contract_unverified')}

async function initTransaction(){const jar:Jar=new Map(),r1=await request(START,{method:'GET',headers:{accept:'text/html,application/xhtml+xml'}},jar),loc=r1.headers.get('location');if(!loc)throw Error('provider_contract_unverified');const loginUrl=new URL(loc,START).href,r2=await request(loginUrl,{method:'GET',headers:{accept:'text/html,application/xhtml+xml'}},jar),html=await r2.text();if(!r2.ok||!hasCredentialForm(html))throw Error('provider_contract_unverified');const form=primaryForm(html);if(!form)throw Error('provider_contract_unverified');return{jar,loginUrl,html,form}}
async function passwordLogin(state:any,emailValue:any,passwordValue:any){const flow=await flowByState(state),userId=uuid(flow.user_id),account=email(emailValue),password=String(passwordValue||'');if(!account||!password||password.length>1024)throw Error('login_failed');await eligible(userId);const tx=await initTransaction(),fields=formInputs(tx.form.html);fields.username=account;fields.password=password;const target=tx.form.action?new URL(tx.form.action,tx.loginUrl).href:tx.loginUrl,r=await request(target,{method:'POST',headers:{accept:'text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8','content-type':'application/x-www-form-urlencoded','origin':'https://signin.immowelt.de','referer':tx.loginUrl},body:new URLSearchParams(fields)},tx.jar);return settle(flow,account,target,r,tx.jar,true)}
async function mfaStart(ticketValue:any,factorId:any){if(String(factorId||'')!=='immowelt_code')throw Error('mfa_factor_unsupported');const data=await openMfa(String(ticketValue||''));await flowByState(data.flowState,data.userId);return{status:'mfa_code_required',authenticated:false,mfaRequired:true,codeDispatched:true,mfaTicket:String(ticketValue),factors:[{id:'immowelt_code',type:data.type,label:factorLabel(data.type)}]}}
async function mfaVerify(ticketValue:any,factorId:any,passCodeValue:any){if(String(factorId||'')!=='immowelt_code')throw Error('mfa_factor_unsupported');const code=String(passCodeValue||'').trim();if(!/^[A-Za-z0-9-]{4,16}$/.test(code))throw Error('mfa_invalid_code');const data=await openMfa(String(ticketValue||'')),flow=await flowByState(data.flowState,data.userId),jar:Jar=new Map();for(const row of Array.isArray(data.cookies)?data.cookies:[])jar.set(cookieKey(row),row);const fields={...(data.hidden||{})};fields[String(data.codeField||'code')]=code;const r=await request(String(data.url),{method:'POST',headers:{accept:'text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8','content-type':'application/x-www-form-urlencoded','origin':'https://signin.immowelt.de','referer':String(data.url)},body:new URLSearchParams(fields)},jar);try{return await settle(flow,String(data.email),String(data.url),r,jar,false)}catch(e:any){if(e?.message==='provider_interactive_challenge'||e?.message==='login_failed')throw Error('mfa_invalid_code');throw e}}

const SAFE=new Set(['configuration_unavailable','credential_key_invalid','premium_required','invalid_user','invalid_state','auth_flow_expired','login_failed','temporary_network_error','provider_contract_unverified','provider_completion_failed','provider_interactive_challenge','human_verification_required','device_confirmation_required','mfa_required','mfa_factor_unsupported','mfa_invalid_code','mfa_challenge_failed','mfa_expired','invalid_action']);
function response(body:any,status=200){return Response.json(body,{status,headers:{'cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'no-referrer'}})}
function failure(e:any){const code=String(e?.message||'immowelt_auth_failed'),status=code==='login_failed'||code==='mfa_invalid_code'?401:code==='premium_required'?403:code==='auth_flow_expired'||code==='invalid_state'||code==='mfa_expired'?410:code.startsWith('mfa_')||code==='provider_interactive_challenge'||code==='human_verification_required'||code==='device_confirmation_required'?409:503;return response({error:SAFE.has(code)?code:'immowelt_auth_failed'},status)}

Deno.serve(async req=>{try{if(req.method!=='POST')return new Response('method not allowed',{status:405});if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});const body=await req.json().catch(()=>({})),action=String(body.action||'');if(action==='health')return response({ok:true,mode:'immowelt-direct-auth0-universal-login',passwordStored:false,mfaStored:false});if(action==='password_login')return response(await passwordLogin(body.state,body.email,body.password));if(action==='mfa_start')return response(await mfaStart(body.mfaTicket,body.factorId));if(action==='mfa_verify')return response(await mfaVerify(body.mfaTicket,body.factorId,body.passCode));throw Error('invalid_action')}catch(e){return failure(e)}});

import {createClient} from 'npm:@supabase/supabase-js@2.112.4';
import {getConnection} from './credentials.ts';

const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});

async function secret(name:string){const{data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)throw Error('configuration_unavailable');return String(data)}
function active(cookies:any[]){const now=Date.now()/1000;return (Array.isArray(cookies)?cookies:[]).filter((c:any)=>c&&c.name&&c.value&&(Number(c.expires||-1)<0||Number(c.expires||-1)>now))}
function cookieHeader(cookies:any[],urlValue:string){
 const url=new URL(urlValue),host=url.hostname.toLowerCase(),path=url.pathname||'/';
 return active(cookies).filter((c:any)=>{
  const raw=String(c.domain||'').toLowerCase(),domain=raw.replace(/^\./,'');
  const hostOnly=c.hostOnly===true||(c.hostOnly==null&&!raw.startsWith('.'));
  const domainOk=hostOnly?host===domain:(host===domain||host.endsWith('.'+domain));
  return domainOk&&path.startsWith(String(c.path||'/'))&&(!c.secure||url.protocol==='https:');
 }).map((c:any)=>String(c.name)+'='+String(c.value)).join('; ');
}
function safeSnippet(text:string,needle:string){
 const lower=text.toLowerCase(),n=needle.toLowerCase(),i=lower.indexOf(n);
 if(i<0)return null;
 return text.slice(Math.max(0,i-500),Math.min(text.length,i+1800))
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[email]')
  .replace(/\+?\d[\d\s().\/-]{6,}\d/g,'[phone]');
}
function scripts(html:string,base:string){
 const out:string[]=[];const re=/<script[^>]+src=["']([^"']+)["']/gi;let m;
 while((m=re.exec(html))&&out.length<120){try{out.push(new URL(m[1],base).href)}catch{}}
 return [...new Set(out)];
}
async function fetchText(url:string,cookies:any[],ua:string){
 const headers:any={accept:'text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8','accept-language':'de-DE,de;q=0.9,en;q=0.8','user-agent':ua};
 const ch=cookieHeader(cookies,url);if(ch)headers.cookie=ch;
 const response=await fetch(url,{headers,redirect:'follow',signal:AbortSignal.timeout(25000)});
 const text=await response.text();
 return{response,text};
}
async function inspectPage(url:string,cookies:any[],ua:string){
 const {response,text}=await fetchText(url,cookies,ua);
 const needles=['contact-request-service','householdType','houseHoldType','workStatus','netMonthlyIncome','totalNetIncomeBeforeTaxRange','preferredMoveInDate','classifiedId','contacting'];
 return{
  httpStatus:response.status,finalUrl:response.url,bytes:text.length,
  snippets:Object.fromEntries(needles.map(n=>[n,safeSnippet(text,n)]).filter(([,v])=>v)),
  scripts:scripts(text,response.url)
 };
}
async function inspectScripts(urls:string[],cookies:any[],ua:string){
 const needles=['householdType','workStatus','netMonthlyIncome','preferredMoveInDate','contact-request-service','contacting','totalNetIncomeBeforeTaxRange'];
 const hits:any[]=[];
 for(const url of urls.slice(0,80)){
  let response:Response,text='';
  try{
   const headers:any={'user-agent':ua,accept:'*/*'};const ch=cookieHeader(cookies,url);if(ch)headers.cookie=ch;
   response=await fetch(url,{headers,redirect:'follow',signal:AbortSignal.timeout(12000)});
   if(!response.ok)continue;text=await response.text();
  }catch{continue}
  const found=needles.filter(n=>text.toLowerCase().includes(n.toLowerCase()));
  if(found.length){
   hits.push({url,bytes:text.length,found,snippets:Object.fromEntries(found.map(n=>[n,safeSnippet(text,n)]))});
   if(hits.length>=8)break;
  }
 }
 return hits;
}
Deno.serve(async req=>{
 try{
  if(req.method!=='POST')return Response.json({error:'method_not_allowed'},{status:405});
  if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return Response.json({error:'forbidden'},{status:403});
  const body=await req.json().catch(()=>({}));
  const userId=String(body.userId||''),ids=Array.isArray(body.onlineIds)?body.onlineIds.map(String).filter(Boolean).slice(0,4):[];
  const connection=await getConnection(db,userId,'immowelt');if(!connection)return Response.json({error:'no_connection'},{status:404});
  const cookies=Array.isArray(connection.credentials?.cookies)?connection.credentials.cookies:[],ua=String(connection.credentials?.userAgent||'Mozilla/5.0');
  const results=[];
  for(const id of ids){
   const url='https://www.immowelt.de/expose/'+encodeURIComponent(id),page=await inspectPage(url,cookies,ua);
   const scriptHits=await inspectScripts(page.scripts,cookies,ua);
   results.push({onlineId:id,page:{httpStatus:page.httpStatus,finalUrl:page.finalUrl,bytes:page.bytes,snippets:page.snippets,scriptCount:page.scripts.length},scriptHits});
  }
  return Response.json({results},{headers:{'cache-control':'no-store'}});
 }catch(e:any){return Response.json({error:String(e?.message||'diagnostic_failed')},{status:500})}
});

const enc=new TextEncoder(),dec=new TextDecoder();
const b64=(bytes:Uint8Array)=>{let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s)};
const unb64=(value:string)=>Uint8Array.from(atob(value),c=>c.charCodeAt(0));
async function keyMaterial(db:any,version=1){const name=`application_credential_key_v${version}`;const {data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)throw Error('credential_key_unavailable');const raw=unb64(String(data));if(raw.length!==32)throw Error('credential_key_invalid');return crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt']);}
export async function encryptCredentials(db:any,userId:string,provider:string,value:unknown,keyVersion=1){const key=await keyMaterial(db,keyVersion),iv=crypto.getRandomValues(new Uint8Array(12));const aad=enc.encode(`${userId}:${provider}:v${keyVersion}`);const plain=enc.encode(JSON.stringify(value));const cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad},key,plain));return {credential_ciphertext:b64(cipher),credential_iv:b64(iv),key_version:keyVersion};}
export async function decryptCredentials(db:any,row:any){if(!row?.credential_ciphertext||!row?.credential_iv)return null;const version=Number(row.key_version)||1,key=await keyMaterial(db,version),aad=enc.encode(`${row.user_id}:${row.provider}:v${version}`);try{const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(row.credential_iv),additionalData:aad},key,unb64(row.credential_ciphertext));return JSON.parse(dec.decode(plain));}catch{throw Error('credential_decrypt_failed');}}
export async function saveConnection(db:any,userId:string,provider:string,credentials:unknown,patch:any={}){const encrypted=credentials==null?{credential_ciphertext:null,credential_iv:null,key_version:1}:await encryptCredentials(db,userId,provider,credentials,1);const {error}=await db.from('platform_connections').upsert({user_id:userId,provider,status:'connected',...encrypted,last_verified_at:new Date().toISOString(),last_error:null,...patch},{onConflict:'user_id,provider'});if(error)throw Error('connection_save_failed');}
export async function getConnection(db:any,userId:string,provider:string){const {data,error}=await db.from('platform_connections').select('*').eq('user_id',userId).eq('provider',provider).maybeSingle();if(error)throw Error('connection_read_failed');return data?{row:data,credentials:await decryptCredentials(db,data)}:null;}
export async function markConnection(db:any,userId:string,provider:string,status:string,lastError:string|null=null,patch:any={}){const {error}=await db.from('platform_connections').upsert({user_id:userId,provider,status,last_error:lastError,updated_at:new Date().toISOString(),...patch},{onConflict:'user_id,provider'});if(error)throw Error('connection_update_failed');}
export async function deleteConnection(db:any,userId:string,provider:string){const {error}=await db.from('platform_connections').delete().eq('user_id',userId).eq('provider',provider);if(error)throw Error('disconnect_failed');}

